/**
 * فهرست نسخه‌ها — هم صفحه‌ی «نسخه برنامه» و هم راهنمای هوشمند پنل از آن می‌خوانند.
 *
 * متن هر نسخه برای کاربر نهایی است: بدون نام سایت و بدون شرح ایراد، فقط بهبودها.
 * دستیار با جستجو در همین متن جواب «این قابلیت کجاست» را می‌دهد (docs/plans/admin-assistant.md بخش ۵)،
 * پس هر قابلیت تازه را با نام صفحه و دکمه‌ای که کاربر می‌بیند بنویسید.
 */

export type ChangeType = "feature" | "improvement" | "fix" | "security";

export interface ReleaseNote {
  version: string;
  date: string;
  tag: "major" | "minor" | "patch";
  title: string;
  description?: string;
  changes: { type: ChangeType; text: string }[];
}

